<?php
/** Proof — JSON mode (spec "Proof", 6): every handler under a signed action token answers {ok, did, location}; 422 {error:{code invalid, fields}}; _partial=1; a run token's rows are source agent and the rights hold. */
require __DIR__ . '/lib.php';
$fx = ap_fixture();
$bea = ['X-Action-Token: ' . person_token(27)]; $carl = ['X-Action-Token: ' . person_token(28)]; $owner = ['X-Action-Token: ' . person_token(1)];
$wrong = []; $count = 0;
$call = function (string $label, string $path, array $form, array $h, bool $location = true) use (&$wrong, &$count): array {
    [$c, $b] = act_token($path, $form, $h);
    $count++;
    if ($c !== 200 || !($b['ok'] ?? false) || !isset($b['did']) || ($location && !isset($b['location']))) { $wrong[] = "$label $c " . msg($b); }
    return $b;
};
echo "1. Vendors\n";
$b = $call('vendor_save', '/vendors/save.php', ['name' => 'SMOKE Json Vendor', 'email' => 'json@example.invalid', 'terms_days' => '10', 'pay_method' => 'ach'], $bea);
$V = (int) $b['record_id'];
ok(preg_match('#^/vendors/' . $V . '\?notice=saved$#', $b['location']) === 1, 'vendor_save: record_id and a location ending in it');
$call('vendor_save (update)', '/vendors/save.php', ['vendor' => $V, 'phone' => '555'], $bea);
$b = $call('contact_save', '/customers/contact.php', ['party_kind' => 'vendor', 'party' => $V, 'name' => 'SMOKE Jo', 'email' => 'jo@example.invalid', 'is_primary' => 'yes'], $bea);
$call('contact_remove', '/customers/contact-remove.php', ['contact' => $b['record_id']], $bea);
echo "2. Bills\n";
$lines = json_encode([['description' => 'Json line', 'quantity' => '2', 'unit_price' => '50.00', 'expense_account' => '6200', 'tax_rate' => (string) $fx['tax']]]);
$b = $call('bill_draft', '/bills/save.php', ['vendor' => $V, 'vendor_ref' => 'J-1', 'bill_date' => '2026-06-01', 'due_date' => '2026-06-20', 'memo' => 'SMOKE json', 'lines' => $lines], $bea);
$bill = (int) $b['record_id'];
ok(preg_match('#^/bills/' . $bill . '\?notice=saved$#', $b['location']) === 1 && preg_match('/^BILL-\d{6}$/', (string) ($b['number'] ?? '')) === 1 && ($b['has_document'] ?? null) === false, 'bill_draft: record_id, the location, the number, has_document false');
$call('bill_update', '/bills/save.php', ['bill' => $bill, 'memo' => 'SMOKE json changed'], $bea);
$b = $call('bill_line_save', '/bills/line-save.php', ['bill' => $bill, 'description' => 'Second', 'quantity' => '1', 'unit_price' => '10', 'expense_account' => '6100'], $bea);
ok(isset($b['totals']['total']) && $b['totals']['total'] === '118.25', 'a line write answers the totals (118.25)');
$call('bill_line_save (change)', '/bills/line-save.php', ['bill' => $bill, 'line' => $b['record_id'], 'quantity' => '2'], $bea);
$call('bill_line_remove', '/bills/line-remove.php', ['bill' => $bill, 'line' => $b['record_id']], $bea);
$b = $call('bill_approve', '/bills/approve.php', ['bill' => $bill], $carl);
ok(($b['amount'] ?? '') === '108.25' && ($b['has_document'] ?? null) === false && ($b['currency'] ?? '') === 'USD', 'bill_approve answers the amount (108.25 gross) and has_document');
$v = (int) act_token('/bills/save.php', ['vendor' => $V, 'bill_date' => '2026-06-02', 'lines' => $lines], $bea)[1]['record_id'];
act_token('/bills/approve.php', ['bill' => $v], $carl);
$call('bill_void', '/bills/void.php', ['bill' => $v, 'reason' => 'SMOKE json void'], $carl);
$dd = (int) act_token('/bills/save.php', ['vendor' => $V, 'lines' => $lines], $bea)[1]['record_id'];
$call('bill_delete', '/bills/delete.php', ['bill' => $dd], $bea);
echo "3. Payments and runs\n";
$b = $call('payment_draft', '/payments/save.php', ['vendor' => $V, 'bank_account' => $fx['bank'], 'method' => 'cheque', 'payment_date' => '2026-06-15', 'bills' => [$bill]], $bea);
$pay = (int) $b['record_id'];
ok(preg_match('#^/payments/' . $pay . '\?notice=saved$#', $b['location']) === 1 && ($b['applied'][0]['amount'] ?? '') === '108.25', 'payment_draft: record_id, location, applied[] (108.25)');
$call('payment_update', '/payments/save.php', ['payment' => $pay, 'reference' => 'SMOKE ref'], $bea);
$call('payment_unapply', '/payments/unapply.php', ['payment' => $pay, 'bill' => $bill], $bea);
$call('payment_apply', '/payments/apply.php', ['payment' => $pay, 'bill' => $bill], $bea);
$b = $call('payment_approve', '/payments/approve.php', ['payment' => $pay], $carl);
$b = $call('payment_record', '/payments/record.php', ['payment' => $pay, 'payment_date' => '2026-06-16', 'cheque_number' => '9001'], $bea);
ok(($b['applied'][0]['number'] ?? '') !== '' && preg_match('#^/payments/' . $pay . '\?notice=recorded$#', $b['location']) === 1, 'payment_record answers applied[] and the location');
$call('payment_void', '/payments/void.php', ['payment' => $pay, 'reason' => 'SMOKE json void'], $carl);
$d2 = mk_payment($V, $fx['bank'], [$bill], ['method' => 'ach']);
$call('payment_delete', '/payments/delete.php', ['payment' => $d2], $bea);
$bill2 = (int) act_token('/bills/save.php', ['vendor' => $V, 'bill_date' => '2026-06-03', 'due_date' => '2026-06-20', 'lines' => $lines], $bea)[1]['record_id'];
act_token('/bills/approve.php', ['bill' => $bill2], $carl);
$call('vendor_save (cheque)', '/vendors/save.php', ['vendor' => $V, 'pay_method' => 'cheque'], $bea);
$b = $call('payment_run_create', '/payment-runs/save.php', ['bank_account' => $fx['bank'], 'pay_date' => '2026-06-30', 'bills' => [$bill, $bill2]], $bea);
$run = (int) $b['record_id'];
ok(preg_match('#^/payment-runs/' . $run . '\?notice=saved$#', $b['location']) === 1 && count($b['payments'] ?? []) === 1 && ($b['amount'] ?? '') === '216.50', 'payment_run_create: record_id, location, payments[], amount 216.50');
$pid = (int) $b['payments'][0]['payment_id'];
$call('payment_run_remove', '/payment-runs/remove.php', ['payment_run' => $run, 'payment' => $pid], $bea);
$call('payment_run_add', '/payment-runs/add.php', ['payment_run' => $run, 'payment' => $pid], $bea);
$b = $call('payment_run_approve', '/payment-runs/approve.php', ['payment_run' => $run, 'first_cheque_number' => '5001'], $carl);
ok(($b['cheques'][0]['cheque_number'] ?? '') === '5001', 'payment_run_approve answers the cheques numbered');
$call('payment_run_record', '/payment-runs/record.php', ['payment_run' => $run, 'pay_date' => '2026-07-01'], $bea);
$bill3 = (int) act_token('/bills/save.php', ['vendor' => $V, 'bill_date' => '2026-06-04', 'due_date' => '2026-06-21', 'lines' => $lines], $bea)[1]['record_id'];
act_token('/bills/approve.php', ['bill' => $bill3], $carl);
$run2 = (int) act_token('/payment-runs/save.php', ['bank_account' => $fx['bank'], 'pay_date' => '2026-07-02', 'bills' => [$bill3]], $bea)[1]['record_id'];
$call('payment_run_void', '/payment-runs/void.php', ['payment_run' => $run2, 'reason' => 'SMOKE json'], $carl);
echo "4. Vendor credits, archive, delete\n";
$bill4 = (int) act_token('/bills/save.php', ['vendor' => $V, 'bill_date' => '2026-06-05', 'due_date' => '2026-06-22', 'lines' => $lines], $bea)[1]['record_id'];
act_token('/bills/approve.php', ['bill' => $bill4], $carl);
$b = $call('vendor_credit_draft', '/vendor-credits/save.php', ['vendor' => $V, 'bill' => $bill4, 'lines' => json_encode([['description' => 'Json credit', 'quantity' => '1', 'unit_price' => '20.00', 'expense_account' => '6200']])], $bea);
$vc = (int) $b['record_id'];
$call('vendor_credit_update', '/vendor-credits/save.php', ['vendor_credit' => $vc, 'reason' => 'SMOKE json'], $bea);
$b = $call('vendor_credit_line_save', '/vendor-credits/line-save.php', ['vendor_credit' => $vc, 'description' => 'More', 'quantity' => '1', 'unit_price' => '5', 'expense_account' => '6200'], $bea);
$call('vendor_credit_line_remove', '/vendor-credits/line-remove.php', ['vendor_credit' => $vc, 'line' => $b['record_id']], $bea);
$call('vendor_credit_issue', '/vendor-credits/issue.php', ['vendor_credit' => $vc], $carl);
$call('vendor_credit_apply', '/vendor-credits/apply.php', ['vendor_credit' => $vc, 'bill' => $bill4, 'amount' => '10'], $bea);
$call('vendor_credit_unapply', '/vendor-credits/unapply.php', ['vendor_credit' => $vc, 'bill' => $bill4], $bea);
$call('vendor_credit_void', '/vendor-credits/void.php', ['vendor_credit' => $vc, 'reason' => 'SMOKE json'], $carl);
$vc2 = (int) act_token('/vendor-credits/save.php', ['vendor' => $V, 'lines' => json_encode([['description' => 'Delete me', 'quantity' => '1', 'unit_price' => '1', 'expense_account' => '6200']])], $bea)[1]['record_id'];
$call('vendor_credit_delete', '/vendor-credits/delete.php', ['vendor_credit' => $vc2], $bea);
$arch = (int) act_token('/vendors/save.php', ['name' => 'SMOKE Json Archive'], $bea)[1]['record_id'];
$call('vendor_archive', '/vendors/archive.php', ['vendor' => $arch], $bea);
$call('vendor_delete', '/vendors/delete.php', ['vendor' => $arch], $owner);
ok($wrong === [], "$count handlers answer {ok, did, location}" . ($wrong ? ' — wrong: ' . implode('; ', $wrong) : ''));
echo "5. Refusals\n";
[$c, $b] = act_token('/bills/save.php', ['vendor' => '', 'bill_date' => 'x', 'due_date' => 'y'], $bea);
$f = fields($b);
ok($c === 422 && ($b['error']['code'] ?? '') === 'invalid' && isset($f['vendor'], $f['bill_date'], $f['due_date']) && count($b['error']['errors']) === 3, 'a bad bill form: 422 {error: {code invalid, errors[3], fields{vendor, bill_date, due_date}}}');
[$c, $b] = act_token('/bills/save.php', ['vendor' => $V, 'lines' => json_encode([['description' => 'x', 'quantity' => '0', 'unit_price' => '1', 'expense_account' => '6200'], ['description' => 'y', 'quantity' => '1', 'unit_price' => '1']])], $bea);
ok($c === 422 && str_contains(msg($b), 'Row 1: the quantity is a number above zero') && (fields($b)['row'] ?? 0) === 1, 'a bad line row: 422 naming the row');
[$c, $b] = act_token('/bills/save.php', ['vendor' => $V, 'lines' => json_encode([['description' => 'y', 'quantity' => '1', 'unit_price' => '1', 'expense_account' => '4100']])], $bea);
ok($c === 422 && str_contains(msg($b), 'Row 1:') && str_contains(msg($b), 'expense account'), 'an income account code on a bill line: 422 naming the row (' . msg($b) . ')');
[$c, $b] = act_token('/bills/save.php', ['vendor' => $V, 'vendor_ref' => 'J-1', 'lines' => $lines], $bea);
ok($c === 422 && ($b['error']['fields']['record_id'] ?? 0) === $bill && str_contains(msg($b), 'is already entered as'), 'a duplicate vendor reference: 422 with the existing bill\'s id in fields.record_id');
[$c, $b] = act_token('/bills/approve.php', ['bill' => 424242], $carl);
ok($c === 404 && msg($b) === 'Bill not found.', 'an unknown bill: 404 in one sentence');
[$c, $b] = act_token('/bills/approve.php', ['bill' => $bill2], $bea);
ok($c === 403, 'the rights hold under a token: the Bookkeeper approving → 403');
[$c, $b] = act_token('/bills/void.php', ['bill' => $bill2, 'reason' => 'x'], $bea);
ok($c === 403 && msg($b) === 'You may not reverse, void or write off.', 'the Bookkeeper voiding → 403');
[$c, $b] = act_token('/payments/save.php', ['vendor' => $V, 'bank_account' => $fx['bank'], 'method' => 'ach', 'amount' => '1'], ['X-Action-Token: ' . person_token(26)]);
ok($c === 403, 'a Viewer preparing a payment → 403');
[$c, $b] = act_token('/payments/save.php', ['vendor' => $V, 'bank_account' => $fx['bank'], 'method' => 'ach', 'amount' => '1'], ['X-Action-Token: ' . person_token(1, -5)]);
ok($c === 401, 'an expired token: 401');
[$c, $b] = act_token('/payments/save.php', ['vendor' => $V, 'bank_account' => $fx['bank'], 'method' => 'wire', 'amount' => 'abc'], $bea);
ok($c === 422 && isset(fields($b)['method'], fields($b)['amount']), 'a bad method and amount: 422 naming both fields');
echo "6. _partial=1 keeps the rest\n";
$p = (int) act_token('/bills/save.php', ['vendor' => $V, 'bill_date' => '2026-07-01', 'due_date' => '2026-07-20', 'vendor_ref' => 'KEEP-ME', 'memo' => 'first', 'lines' => $lines], $bea)[1]['record_id'];
[$c, $b] = act_token('/bills/save.php', ['bill' => $p, 'memo' => 'changed', '_partial' => '1'], $bea);
$row = bill_row($p);
ok($c === 200 && $row['memo'] === 'changed' && $row['vendor_ref'] === 'KEEP-ME' && $row['due_date'] === '2026-07-20' && (int) $row['vendor_id'] === $V, 'bill_update with _partial=1: the base row fills the rest');
$vcp = (int) act_token('/vendor-credits/save.php', ['vendor' => $V, 'reason' => 'keep this', 'lines' => '[]'], $bea)[1]['record_id'];
[$c, $b] = act_token('/vendor-credits/save.php', ['vendor_credit' => $vcp, 'credit_date' => '2026-08-01', '_partial' => '1'], $bea);
ok($c === 200 && (string) one('SELECT reason FROM vendor_credits WHERE id = :c', ['c' => $vcp]) === 'keep this', 'vendor_credit_update with _partial=1 too');
$pp = mk_payment($V, $fx['bank'], [], ['amount' => '12.50', 'method' => 'cash']);
[$c, $b] = act_token('/payments/save.php', ['payment' => $pp, 'memo' => 'partial memo', '_partial' => '1'], $bea);
$r = pay_row($pp);
ok($c === 200 && $r['memo'] === 'partial memo' && $r['amount'] === '12.50' && $r['method'] === 'cash' && (int) $r['bank_account_id'] === $fx['bank'], 'payment_update with _partial=1 keeps amount, method and bank account');
[$c, $b] = act_token('/vendors/save.php', ['vendor' => $V, 'notes' => 'partial note', '_partial' => '1'], $bea);
ok($c === 200 && (string) one('SELECT name FROM vendors WHERE id = :c', ['c' => $V]) === 'SMOKE Json Vendor' && (string) one('SELECT terms_days FROM vendors WHERE id = :c', ['c' => $V]) === '10' && (string) one('SELECT pay_method FROM vendors WHERE id = :c', ['c' => $V]) === 'cheque', 'vendor_save with _partial=1 keeps the rest');
echo "7. An agent's run token\n";
kernel_state(function ($st) { $st['facts']['73'] = ['valid' => true, 'is_agent' => true, 'member_id' => 40, 'run_id' => 73, 'request_id' => 'req-run-73', 'trigger' => 'duty', 'is_eval' => false, 'endpoints' => [['name' => 'Records MCP']]]; return $st; });
[$tok, $relay] = run_token(40, 73);
$h = ['X-Action-Token: ' . $tok, 'X-Action-Relay: ' . $relay];
$since = last_activity_id();
[$c, $b] = act_token('/bills/save.php', ['vendor' => $V, 'vendor_ref' => 'AGENT-1', 'lines' => $lines], $h);
$agentBill = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $agentBill > 0, 'the Bookkeeper agent drafts a bill (ap.write)');
$rows = q("SELECT source, agent_run_id, request_id FROM activity_log WHERE id > :s AND action = 'bill.draft'", ['s' => $since]);
ok(count($rows) === 1 && $rows[0]['source'] === 'agent' && (int) $rows[0]['agent_run_id'] === 73 && $rows[0]['request_id'] === 'req-run-73', 'its row is source agent, run 73, the run\'s request id');
[$c, $b] = act_token('/bills/approve.php', ['bill' => $agentBill], $h);
ok($c === 403, 'the agent may not approve (ap.approve): 403 — an agent\'s drafts wait for the Controller');
[$c, $b] = act_token('/bills/void.php', ['bill' => $agentBill, 'reason' => 'x'], $h);
ok($c === 403, 'nor void (journal.override): 403');
[$c, $b] = act_token('/vendors/delete.php', ['vendor' => $V], $h);
ok($c === 403, 'nor delete a vendor: 403');
[$c, $b] = act_token('/bills/save.php', ['vendor' => $V, 'lines' => '[]'], ['X-Action-Token: ' . $tok]);
ok($c === 401, 'the relay missing: 401');
kernel_state(function ($st) { unset($st['facts']); return $st; });
echo "8. The screens answer JSON\n";
$hj = array_merge(JSONH, $bea);
$r = req('GET', '/bills/' . $bill, ['headers' => $hj]); $d = json_decode($r['body'], true)['data'] ?? [];
ok($r['code'] === 200 && $d['bill']['bill_id'] === $bill && isset($d['bill']['lines'], $d['bill']['payments'], $d['bill']['credits'], $d['attachments'], $d['timeline'], $d['may']) && ($d['bill']['has_document'] ?? null) === false, 'the bill: head, lines, payments, credits, has_document, attachments, timeline');
$bad = [];
foreach (['/vendors/', '/vendors/' . $V, '/vendors/new', '/vendors/' . $V . '/edit', '/bills/', '/bills/new', '/bills/' . $bill . '/edit?x=1', '/vendor-credits/', '/vendor-credits/' . $vc, '/vendor-credits/new', '/payments/', '/payments/' . $pay, '/payments/new?vendor=' . $V, '/payment-runs/', '/payment-runs/' . $run, '/payment-runs/new?bank_account=' . $fx['bank']] as $path) {
    $r = req('GET', $path, ['headers' => $hj]);
    if ($path === '/bills/' . $bill . '/edit?x=1') { if ($r['code'] !== 422) { $bad[] = "$path {$r['code']}"; } continue; }
    if ($r['code'] !== 200 || !isset(json_decode($r['body'], true)['data'])) { $bad[] = "$path {$r['code']}"; }
}
ok(empty($bad), 'sixteen screens answer JSON (an approved bill\'s edit form: 422)' . (empty($bad) ? '' : ' — wrong: ' . implode('; ', $bad)));
finish();
